//! A container module's functions (SINCE media 1.5): what media.library
//! calls a kind of container's code in LIBS:codecs/ with
//! (sdk/libs/media/mcontainer.zig); the base is the module's, opened with
//! OpenLibrary("codecs/<kind>.container"). Two tasks may each read a track
//! of their own at once; `file.lock` lets one at a time at the source. A
//! module answers MERR_UNSUPPORTED to a file whose layout is not its own.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/mcontainer_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const mcontainer = @import("../libs/media/mcontainer.zig");
const media = @import("../libs/media/media.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "mcontainer";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const OpenContainer = libraries.lvo(4);
    pub const CloseContainer = libraries.lvo(5);
    pub const ReadContainerPacket = libraries.lvo(6);
    pub const SeekContainer = libraries.lvo(7);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const OpenContainer = *const fn (*MContainerBase, *mcontainer.MediaContainerFile, bool) callconv(.c) i32;
    pub const CloseContainer = *const fn (*MContainerBase, *mcontainer.MediaContainerFile) callconv(.c) void;
    pub const ReadContainerPacket = *const fn (*MContainerBase, *mcontainer.MediaContainerFile, u32, *media.MediaPacket) callconv(.c) i32;
    pub const SeekContainer = *const fn (*MContainerBase, *mcontainer.MediaContainerFile, u32, i64) callconv(.c) i32;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const MContainerBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *MContainerBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The file's index read, its tracks and tags made out of it, and every
    /// track at its first packet: 0, or MERR_*. With `check`, MERR_UNKNOWN when
    /// the bytes are not its kind's. On what opened the file, which it reads.
    pub fn OpenContainer(self: *MContainerBase, file: *mcontainer.MediaContainerFile, check: bool) i32 {
        return libraries.call(self, LVO.OpenContainer, Fn.OpenContainer, .{ file, check });
    }

    /// What the module holds of the file given back, if it made anything:
    /// after a failed open too. The file and its tracks' buffers stay the
    /// library's.
    pub fn CloseContainer(self: *MContainerBase, file: *mcontainer.MediaContainerFile) void {
        return libraries.call(self, LVO.CloseContainer, Fn.CloseContainer, .{file});
    }

    /// The track's next packet into `packet`: 0, MERR_END, or MERR_*. Its
    /// bytes are in the track's buffer, good until the track's next read or
    /// seek.
    pub fn ReadContainerPacket(self: *MContainerBase, file: *mcontainer.MediaContainerFile, track: u32, packet: *media.MediaPacket) i32 {
        return libraries.call(self, LVO.ReadContainerPacket, Fn.ReadContainerPacket, .{ file, track, packet });
    }

    /// The track moved to the key packet at or before `time`, in microseconds:
    /// 0, or MERR_*. The file can seek; `track` is one it has.
    pub fn SeekContainer(self: *MContainerBase, file: *mcontainer.MediaContainerFile, track: u32, time: i64) i32 {
        return libraries.call(self, LVO.SeekContainer, Fn.SeekContainer, .{ file, track, time });
    }
};
